"""Function signatures, prototype scopes and pointer declarations; no indirect ABI."""
valid = [
    ("function-type-guest", b'typedef int F(int);F *p=0;int main(){return sizeof(F)+sizeof(p)+2;}', 7),
    ("function-type-abstract", b'int main(){return sizeof(int(int))+_Alignof(int(int))+sizeof(int(*)(int));}', 6),
    ("function-type-local-pointer", b'int main(){int (*p)(int)=0;return p==0?7:9;}', 7),
    ("function-type-pointer-array", b'int (*p[2])(int)={0,0};int main(){return sizeof(p);}', 8),
    ("function-type-member", b'struct S{int (*p)(int);int n;}s={0,7};int main(){return s.n;}', 7),
    ("function-type-parameter", b'int f(int (*p)(int)){return p==0?7:9;}int main(){return f(0);}', 7),
    ("function-type-parameter-decay", b'int f(int p(int)){return p==0?7:9;}int main(){return f(0);}', 7),
    ("function-type-generic", b'int main(){int (*p)(int)=0;return _Generic(p,int(*)(int):7,default:9);}', 7),
    ("function-type-return-pointer", b'int main(){return __builtin_types_compatible_p(int*(*)(int),typeof(int*(*)(int)));}', 1),
    ("function-type-compatible", b'typedef int F(int);typedef int G(int n);int main(){return __builtin_types_compatible_p(F,G);}', 1),
    ("function-type-incompatible-return", b'int main(){return __builtin_types_compatible_p(int(int),long(int));}', 0),
    ("function-type-incompatible-parameter", b'int main(){return __builtin_types_compatible_p(int(int),int(long));}', 0),
    ("function-type-incompatible-count", b'int main(){return __builtin_types_compatible_p(int(int),int(int,int));}', 0),
    ("function-type-parameter-qualifiers", b'int main(){return __builtin_types_compatible_p(int(int),int(const int));}', 1),
    ("function-type-return-qualifiers", b'int main(){return __builtin_types_compatible_p(int(int),const int(int));}', 1),
    ("function-type-typedef-qualifiers", b'typedef int F(int);int main(){return __builtin_types_compatible_p(F,const F);}', 1),
    ("function-type-empty-void", b'int main(){return __builtin_types_compatible_p(int(),int(void));}', 1),
    ("function-type-empty-integer", b'int main(){return __builtin_types_compatible_p(int(),int(int));}', 1),
    ("function-type-empty-character", b'int main(){return __builtin_types_compatible_p(int(),int(char));}', 0),
    ("function-type-variadic", b'int main(){int (*p)(int,...)=0;return _Generic(p,int(*)(int,...):7,default:9);}', 7),
    ("function-type-variadic-different", b'int main(){return __builtin_types_compatible_p(int(int,...),int(int));}', 0),
    ("function-type-variadic-empty", b'int main(){return __builtin_types_compatible_p(int(int,...),int());}', 0),
    ("function-type-array-parameter", b'int main(){return __builtin_types_compatible_p(int(int[3]),int(int*));}', 1),
    ("function-type-nested-callback", b'typedef int F(int (*cb)(int));int main(){return __builtin_types_compatible_p(F,int(int(*)(int)));}', 1),
    ("function-type-named-parameter-typeof", b'typedef int F(int n,typeof(n));int main(){return __builtin_types_compatible_p(F,int(int,int));}', 1),
    ("function-type-named-parameter-bound", b'typedef int F(int n,int a[sizeof(n)]);int main(){return __builtin_types_compatible_p(F,int(int,int*));}', 1),
    ("function-type-prototype-tag-scope", b'typedef int F(struct S{int n;});struct S{int x,y;};int main(){return sizeof(struct S);}', 8),
    ("function-type-prototype-enum-scope", b'typedef int F(enum E{X=3});enum E{X=7};int main(){return X;}', 7),
    ("function-type-private-tag", b'typedef int F(struct S*);struct S{int x;};int main(){return __builtin_types_compatible_p(F,int(struct S*));}', 0),
    ("function-type-outer-tag", b'struct S;typedef int F(struct S*);struct S{int x;};int main(){return __builtin_types_compatible_p(F,int(struct S*));}', 1),
]
invalid = [
    ("function-type-array-functions", b'typedef int F(int);F a[2];int main(){return 0;}'),
    ("function-type-function-return", b'typedef int F(int);typedef F G(int);int main(){return 0;}'),
    ("function-type-array-return", b'typedef int A[2];typedef A F(int);int main(){return 0;}'),
    ("function-type-member-function", b'struct S{int f(int);};int main(){return 0;}'),
    ("function-type-void-named", b'typedef int F(void n);int main(){return 0;}'),
    ("function-type-void-combined", b'typedef int F(int,void);int main(){return 0;}'),
    ("function-type-ellipsis-only", b'typedef int F(...);int main(){return 0;}'),
    ("function-type-trailing-comma", b'typedef int F(int,);int main(){return 0;}'),
    ("function-type-duplicate-parameter", b'typedef int F(int n,int n);int main(){return 0;}'),
    ("function-type-return-array-prototype", b'typedef int A[2];A f(void);int main(){return 0;}'),
    ("function-type-incompatible-pointer-init", b'int (*p)(int)=0;long (*q)(int)=p;int main(){return 0;}'),
    ("function-type-return-value", b'typedef int F(int);int main(){F *p=0;return *p;}'),
]
